{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act ban on algorithmic rent-setting and coordinating functions","requirement":"A rental property owner, or its agent, representative or subcontractor, may not subscribe to, contract for or otherwise use a coordinator's services, and no person may perform a coordinating function or engage in parallel pricing coordination for residential units.","key_value":null,"coverage_conditions":"All residential dwelling units in New Jersey, including an owner performing a coordinating function for its own benefit; inpatient medical care, licensed long-term care, and detention or correctional facilities are excluded.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Any rental property owner, coordinator, agent or subcontractor; residential dwelling units only"},"exemptions":"Research, statistical analysis or testing use of information; free public rent estimates; real estate brokerage databases available on equal terms that do not set or recommend prices; government entities setting rents through affordability controls.","penalty":"A violation is a violation of the New Jersey Antitrust Act, and sections 6 through 17 of P.L.1970, c.73 (C.56:9-6 through 9-17) apply to it.","effective_date":"2027-07-01","citation":"P.L. 2026, c.043 § 4","quoted_span":"It shall be unlawful and a violation of the “New Jersey Antitrust Act,” P.L.1970, c.73 (C.56:9-1 et seq.) for: a. a rental property owner, or any agent, representative, or subcontractor thereof, to receive, subscribe to, contract for, or otherwise exchange any form of consideration in return for the use of, the services of a coordinator;","interaction":"Constructed in addition to the New Jersey Antitrust Act and not authorizing conduct already unlawful under it; municipalities may not enact conflicting ordinances.","confidence":0.93,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act preemption of conflicting municipal ordinances","requirement":"A municipality may not enact an ordinance that conflicts with the FAIR Act, but ordinances explicitly authorized or required by other law are not barred.","key_value":null,"coverage_conditions":"All New Jersey municipalities.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Municipal ordinances regulating rental pricing conduct"},"exemptions":"Ordinances explicitly authorized or required by any other law, such as affordability controls or rent control ordinances.","penalty":null,"effective_date":"2027-07-01","citation":"P.L. 2026, c.043 § 6","quoted_span":"A municipality shall be prohibited from enacting an ordinance that conflicts with this act.  This subsection shall not be construed to prohibit the enactment of ordinances explicitly authorized or required by any other law.","interaction":"Does not prohibit local ordinances explicitly authorized or required by other law, including affordability controls and rent control or rent leveling ordinances.","confidence":0.9,"conflict_flag":false,"conflict_note":null}
